מה מדפיסה התכנית הבאה?
```cpp
class A {
public:
     A(int x = 1) {
          this->x = x;
     }
     ~A() {
          cout << x;
     }
     int x;
};

class B {
public:
     B(int n = 3) {
          this->n = n;
          p = new A[n];
     }
     ~B() {
          delete[] p;
     }
     int n;
     A* p;
};

void main() {
     B* p = new B();
}
```

להלן תיאור חלקי של מחלקות `A` ו- `B` והפונקציה `main`.
```cpp
class B {
public:
     ...
     void f() { ... }
};

class A : public B {
public:
     ...
     void f() { ... }
};

void main()
{
     ...
}
```
בשאלה זו במונח פונקציות חברות הכוונה ל- `member functions`.

